{
  "title": "The Gilded Gauntlet",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined city gates.",
      "visual_description": "Three travelers stand before massive iron gates, twisted and scarred, with a broken royal crest half-hidden beneath moss.",
      "characters": ["Elena", "Dorn", "Lira"]
    },
    {
      "scene_number": 2,
      "caption": "Townspeople whisper warnings in the outer market.",
      "visual_description": "Huddled figures in tattered cloaks point fearfully toward the inner city, their faces lit by a single guttering torch.",
      "characters": ["Elena", "Dorn", "Lira", "Heska"]
    },
    {
      "scene_number": 3,
      "caption": "Armored patrol blocks a narrow street.",
      "visual_description": "Three guards in rusted plate armor raise halberds, their visors down, standing before a crumbling archway.",
      "characters": ["Elena", "Dorn", "Lira", "Captain Vorn"]
    },
    {
      "scene_number": 4,
      "caption": "Elena scouts the old royal palace entrance.",
      "visual_description": "A grand doorway carved with leering griffins, its stone steps cracked and overgrown with thorny vines.",
      "characters": ["Elena"]
    },
    {
      "scene_number": 5,
      "caption": "Dorn disarms a trap in the courtyard.",
      "visual_description": "Dorn kneels beside a pressure plate, his hand hovering over a thin wire while a rusty spike glints nearby.",
      "characters": ["Dorn", "Elena", "Lira"]
    },
    {
      "scene_number": 6,
      "caption": "Lira reads a fading mural of the city's fall.",
      "visual_description": "A fresco showing a king with a cracked crown and a shadowy dragon shape high above the towers.",
      "characters": ["Lira", "Elena", "Dorn"]
    },
    {
      "scene_number": 7,
      "caption": "A cursed tower looms ahead, its door pulsing with runes.",
      "visual_description": "A spiral tower of black stone, its entrance shimmering with sickly green light and carved warnings.",
      "characters": ["Elena", "Dorn", "Lira"]
    },
    {
      "scene_number": 8,
      "caption": "The party enters the tower and faces a mirror trap.",
      "visual_description": "A circular room lined with tall mirrors, each reflecting a different, twisted version of the group.",
      "characters": ["Elena", "Dorn", "Lira"]
    },
    {
      "scene_number": 9,
      "caption": "Dorn shatters the illusion mirror.",
      "visual_description": "Dorn swings a hammer into the central mirror, shards flying as the false reflections scream and dissolve.",
      "characters": ["Dorn", "Elena", "Lira"]
    },
    {
      "scene_number": 10,
      "caption": "They find the captive in a suspended cage.",
      "visual_description": "A rusted iron cage hangs from the tower ceiling, inside a pale figure in torn robes clutches a silver key.",
      "characters": ["Elena", "Dorn", "Lira", "Maren"]
    },
    {
      "scene_number": 11,
      "caption": "A spectral guardian rises from the floor.",
      "visual_description": "A translucent knight in ancient armor, wielding a greatsword of blue flame, drifts upward through the flagstones.",
      "characters": ["Elena", "Dorn", "Lira", "Maren", "Warden Kael"]
    },
    {
      "scene_number": 12,
      "caption": "Lira uses a binding spell to hold the warden.",
      "visual_description": "Golden threads of light shoot from Lira's hands and wrap around the spectral knight, slowing its advance.",
      "characters": ["Lira", "Elena", "Dorn", "Maren", "Warden Kael"]
    },
    {
      "scene_number": 13,
      "caption": "Elena retrieves the key and frees the captive.",
      "visual_description": "Elena turns the silver key in the cage lock, the bars groaning open as Maren stumbles out.",
      "characters": ["Elena", "Maren"]
    },
    {
      "scene_number": 14,
      "caption": "The tower begins to collapse as they flee.",
      "visual_description": "Cracks race up the walls, dust and stone shower down, and the green runes on the door fade to black.",
      "characters": ["Elena", "Dorn", "Lira", "Maren"]
    },
    {
      "scene_number": 15,
      "caption": "Old royal banners hang torn above the escape path.",
      "visual_description": "Tattered pennants with the same broken crest snap in a hot wind, lining a plaza littered with rubble.",
      "characters": ["Elena", "Dorn", "Lira", "Maren"]
    },
    {
      "scene_number": 16,
      "caption": "Patrols converge on the plaza.",
      "visual_description": "Armored figures pour from two side streets, forming a shield wall as Captain Vorn shouts orders.",
      "characters": ["Elena", "Dorn", "Lira", "Maren", "Captain Vorn"]
    },
    {
      "scene_number": 17,
      "caption": "The party races across the stone bridge.",
      "visual_description": "A long, narrow bridge arches over a dry moat filled with jagged rocks, the far gate open and beckoning.",
      "characters": ["Elena", "Dorn", "Lira", "Maren"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the misty hills beyond the city.",
      "visual_description": "Four figures silhouetted against a pale dawn, the ruined city and its temptations fading behind a veil of fog.",
      "characters": ["Elena", "Dorn", "Lira", "Maren"]
    }
  ]
}

